TEST=r'''import dev.settledlands.npc.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.ai.*;import net.minecraft.world.entity.ai.memory.*;import net.minecraft.network.RegistryFriendlyByteBuf;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;import net.neoforged.neoforge.event.entity.player.*;import net.neoforged.neoforge.event.entity.living.*;import net.neoforged.neoforge.event.tick.EntityTickEvent;import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;
public class NetworkStatsTest{
 static void ck(boolean x,String m){if(!x)throw new AssertionError(m);}static NpcStatsNetwork.Open open(ServerPlayer p,GuideNpc n,InteractionHand h){NpcNet.last=null;NpcStatsNetwork.open(p,n,h);ck(NpcNet.last instanceof NpcStatsNetwork.Open,"open sent");return (NpcStatsNetwork.Open)NpcNet.last;}
 static NpcStatsNetwork.Enter enter(NpcStatsNetwork.Open s){return new NpcStatsNetwork.Enter(s.entityId(),s.nonceMost(),s.nonceLeast());}
 public static void main(String[] args){
  RegisterPayloadHandlersEvent re=new RegisterPayloadHandlersEvent();NpcStatsNetwork.register(re);ck(re.r.client==1&&re.r.server==1&&"2".equals(re.version),"payload registration");
  ServerLevel l=new ServerLevel();ServerPlayer p=new ServerPlayer();GuideNpc n=new GuideNpc();p.id=7;n.id=8;l.add(p);l.add(n);n.profile.dialogueGraph.h=11;n.profile.dialogueGraph.d=9;n.profile.dialogueGraph.s=15;
  NpcStatsNetwork.Open s=open(p,n,InteractionHand.MAIN_HAND);ck(s.eligible()&&s.health()==11&&s.damage()==9&&s.speed()==15,"snapshot");RegistryFriendlyByteBuf buf=new RegistryFriendlyByteBuf();NpcStatsNetwork.Open.CODEC.encode(buf,s);ck(NpcStatsNetwork.Open.CODEC.decode(buf).equals(s),"open codec");
  NpcStatsNetwork.Enter req=enter(s);buf=new RegistryFriendlyByteBuf();NpcStatsNetwork.Enter.CODEC.encode(buf,req);ck(NpcStatsNetwork.Enter.CODEC.decode(buf).equals(req),"enter codec");
  NpcStatsNetwork.enter(p,new NpcStatsNetwork.Enter(s.entityId(),s.nonceMost()+1,s.nonceLeast()));ck(PossessionSystem.entered==0&&p.message.contains("stale"),"forged nonce");NpcStatsNetwork.enter(p,req);ck(PossessionSystem.entered==0,"failed token consumed");
  n.cult=0;s=open(p,n,InteractionHand.MAIN_HAND);ck(!s.eligible(),"cult preview");NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0&&p.message.contains("no_cult"),"cult denied");n.cult=1;
  s=open(p,n,InteractionHand.MAIN_HAND);n.cult=0;NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0,"cult changed");n.cult=1;
  s=open(p,n,InteractionHand.MAIN_HAND);n.profile.dialogueGraph.h++;NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0,"changed stats");n.profile.dialogueGraph.h--;
  s=open(p,n,InteractionHand.MAIN_HAND);l.tick+=1201;NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0,"expiry");
  s=open(p,n,InteractionHand.OFF_HAND);p.off=new ItemStack(true);NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0,"tool changed");p.off=new ItemStack();
  s=open(p,n,InteractionHand.MAIN_HAND);p.distance=37;NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0,"distance");p.distance=0;
  s=open(p,n,InteractionHand.MAIN_HAND);p.bodiless=false;NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0,"effect changed");p.bodiless=true;
  s=open(p,n,InteractionHand.MAIN_HAND);n.removed=true;NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0,"removed entity");n.removed=false;
  s=open(p,n,InteractionHand.MAIN_HAND);NpcStatsNetwork.logout(new PlayerEvent.PlayerLoggedOutEvent(p));NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==0,"logout");
  PlayerInteractEvent.EntityInteractSpecific a=new PlayerInteractEvent.EntityInteractSpecific(p,n,InteractionHand.MAIN_HAND);NpcStatsInteraction.specific(a);ck(a.canceled&&a.result==InteractionResult.SUCCESS&&NpcNet.last instanceof NpcStatsNetwork.Open&&PossessionSystem.entered==0,"specific opens only");
  PlayerInteractEvent.EntityInteract b=new PlayerInteractEvent.EntityInteract(p,n,InteractionHand.OFF_HAND);NpcStatsInteraction.generic(b);ck(b.canceled&&b.result==InteractionResult.SUCCESS,"generic opens");
  p.main=new ItemStack(true);a=new PlayerInteractEvent.EntityInteractSpecific(p,n,InteractionHand.MAIN_HAND);NpcStatsInteraction.specific(a);ck(!a.canceled,"editing tool preserved");p.main=new ItemStack();
  GuideCorpseNpc corpse=new GuideCorpseNpc();l.add(corpse);a=new PlayerInteractEvent.EntityInteractSpecific(p,corpse,InteractionHand.MAIN_HAND);NpcStatsInteraction.specific(a);ck(!a.canceled,"corpse preserved");
  Player client=new Player();a=new PlayerInteractEvent.EntityInteractSpecific(client,n,InteractionHand.MAIN_HAND);NpcStatsInteraction.specific(a);ck(a.canceled&&a.result==InteractionResult.SUCCESS,"client blocks dialogue");
  s=open(p,n,InteractionHand.MAIN_HAND);NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==1,"successful possession");n.removed=false;NpcStatsNetwork.enter(p,enter(s));ck(PossessionSystem.entered==1,"nonce replay");
  Mob mob=new Mob();l.add(mob);LivingChangeTargetEvent ev=new LivingChangeTargetEvent(mob,p);NpcBodilessRules.onTarget(ev);ck(ev.target==null,"new target filtered");p.bodiless=false;ev.target=p;NpcBodilessRules.onTarget(ev);ck(ev.target==p,"ordinary target retained");p.bodiless=true;
  CallbackInfoReturnable<Boolean> cb=new CallbackInfoReturnable<>();NpcBodilessRules.rejectTarget(mob,p,cb);ck(cb.set&&Boolean.FALSE.equals(cb.value),"mixin callback");cb=new CallbackInfoReturnable<>();NpcBodilessRules.rejectTarget(p,p,cb);ck(!cb.set,"players see each other");
  mob.target=p;mob.brain.put(MemoryModuleType.ATTACK_TARGET,p);mob.brain.put(MemoryModuleType.HURT_BY_ENTITY,p);mob.brain.put(MemoryModuleType.ANGRY_AT,p.uuid);NpcBodilessRules.onEntityTick(new EntityTickEvent.Pre(mob));ck(mob.target==null,"clear existing target");ck(mob.brain.getMemoryInternal(MemoryModuleType.ATTACK_TARGET).isEmpty()&&mob.brain.getMemoryInternal(MemoryModuleType.HURT_BY_ENTITY).isEmpty()&&mob.brain.getMemoryInternal(MemoryModuleType.ANGRY_AT).isEmpty(),"clear memories");
  mob.brain=new Brain<>();NpcBodilessRules.onEntityTick(new EntityTickEvent.Pre(mob));
  System.out.println("Actual network, guards, both interaction paths and vanilla target rules: PASS");
 }}'''

