  root=pathlib.Path(d);src=root/'src';out=root/'classes';gen_api246.main(src)
  for name,content in OVERRIDE.items():
   file=src/name;file.parent.mkdir(parents=True,exist_ok=True);file.write_text(content+'\n',encoding='utf8')
  (src/'NetworkStatsTest.java').write_text(TEST,encoding='utf8')
